import{_ as t,o as a,c as r,aj as o}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Router reference","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/routing/router-reference.md","filePath":"en/guide/routing/router-reference.md"}'),i={name:"en/guide/routing/router-reference.md"};function s(n,e,l,d,h,c){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="router-reference" tabindex="-1">Router reference <a class="header-anchor" href="#router-reference" aria-label="Permalink to &quot;Router reference&quot;">​</a></h1><p>The following sections highlight some core router concepts and terminology.</p><h2 id="router-events" tabindex="-1">Router events <a class="header-anchor" href="#router-events" aria-label="Permalink to &quot;Router events&quot;">​</a></h2><p>During each navigation, the <code>Router</code> emits navigation events through the <code>Router.events</code> property. These events are shown in the following table.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Router event</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/NavigationStart" target="_blank" rel="noreferrer"><code>NavigationStart</code></a></td><td style="text-align:left;">Triggered when navigation starts.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/RouteConfigLoadStart" target="_blank" rel="noreferrer"><code>RouteConfigLoadStart</code></a></td><td style="text-align:left;">Triggered before the <code>Router</code> lazy loads a route configuration.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/RouteConfigLoadEnd" target="_blank" rel="noreferrer"><code>RouteConfigLoadEnd</code></a></td><td style="text-align:left;">Triggered after a route has been lazy loaded.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/RoutesRecognized" target="_blank" rel="noreferrer"><code>RoutesRecognized</code></a></td><td style="text-align:left;">Triggered when the Router parses the URL and the routes are recognized.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/GuardsCheckStart" target="_blank" rel="noreferrer"><code>GuardsCheckStart</code></a></td><td style="text-align:left;">Triggered when the Router begins the Guards phase of routing.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ChildActivationStart" target="_blank" rel="noreferrer"><code>ChildActivationStart</code></a></td><td style="text-align:left;">Triggered when the Router begins activating a route&#39;s children.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ActivationStart" target="_blank" rel="noreferrer"><code>ActivationStart</code></a></td><td style="text-align:left;">Triggered when the Router begins activating a route.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/GuardsCheckEnd" target="_blank" rel="noreferrer"><code>GuardsCheckEnd</code></a></td><td style="text-align:left;">Triggered when the Router finishes the Guards phase of routing successfully.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ResolveStart" target="_blank" rel="noreferrer"><code>ResolveStart</code></a></td><td style="text-align:left;">Triggered when the Router begins the Resolve phase of routing.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ResolveEnd" target="_blank" rel="noreferrer"><code>ResolveEnd</code></a></td><td style="text-align:left;">Triggered when the Router finishes the Resolve phase of routing successfully.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ChildActivationEnd" target="_blank" rel="noreferrer"><code>ChildActivationEnd</code></a></td><td style="text-align:left;">Triggered when the Router finishes activating a route&#39;s children.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/ActivationEnd" target="_blank" rel="noreferrer"><code>ActivationEnd</code></a></td><td style="text-align:left;">Triggered when the Router finishes activating a route.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/NavigationEnd" target="_blank" rel="noreferrer"><code>NavigationEnd</code></a></td><td style="text-align:left;">Triggered when navigation ends successfully.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/NavigationCancel" target="_blank" rel="noreferrer"><code>NavigationCancel</code></a></td><td style="text-align:left;">Triggered when navigation is canceled. This can happen when a Route Guard returns false during navigation, or redirects by returning a <code>UrlTree</code> or <code>RedirectCommand</code>.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/NavigationError" target="_blank" rel="noreferrer"><code>NavigationError</code></a></td><td style="text-align:left;">Triggered when navigation fails due to an unexpected error.</td></tr><tr><td style="text-align:left;"><a href="https://angular.dev/api/router/Scroll" target="_blank" rel="noreferrer"><code>Scroll</code></a></td><td style="text-align:left;">Represents a scrolling event.</td></tr></tbody></table><p>When you enable the <code>withDebugTracing</code> feature, Angular logs these events to the console.</p><h2 id="router-terminology" tabindex="-1">Router terminology <a class="header-anchor" href="#router-terminology" aria-label="Permalink to &quot;Router terminology&quot;">​</a></h2><p>Here are the key <code>Router</code> terms and their meanings:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Router part</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Router</code></td><td style="text-align:left;">Displays the application component for the active URL. Manages navigation from one component to the next.</td></tr><tr><td style="text-align:left;"><code>provideRouter</code></td><td style="text-align:left;">provides the necessary service providers for navigating through application views.</td></tr><tr><td style="text-align:left;"><code>RouterModule</code></td><td style="text-align:left;">A separate NgModule that provides the necessary service providers and directives for navigating through application views.</td></tr><tr><td style="text-align:left;"><code>Routes</code></td><td style="text-align:left;">Defines an array of Routes, each mapping a URL path to a component.</td></tr><tr><td style="text-align:left;"><code>Route</code></td><td style="text-align:left;">Defines how the router should navigate to a component based on a URL pattern. Routes can include paths, components, child routes, guards, resolvers, and resources.</td></tr><tr><td style="text-align:left;"><code>RouterOutlet</code></td><td style="text-align:left;">The directive (<code>&lt;router-outlet&gt;</code>) that marks where the router displays a view.</td></tr><tr><td style="text-align:left;"><code>RouterLink</code></td><td style="text-align:left;">The directive for binding a clickable HTML element to a route. Clicking an element with a <code>routerLink</code> directive that&#39;s bound to a <em>string</em> or a <em>link parameters array</em> triggers a navigation.</td></tr><tr><td style="text-align:left;"><code>RouterLinkActive</code></td><td style="text-align:left;">The directive for adding/removing classes from an HTML element when an associated <code>routerLink</code> contained on or inside the element becomes active/inactive. It can also set the <code>aria-current</code> of an active link for better accessibility.</td></tr><tr><td style="text-align:left;"><code>ActivatedRoute</code></td><td style="text-align:left;">A service that&#39;s provided to each route component that contains route specific information such as route parameters, static data, resolve data, route resources, global query parameters, and the global fragment.</td></tr><tr><td style="text-align:left;"><code>RouterState</code></td><td style="text-align:left;">The current state of the router including a tree of the currently activated routes together with convenience methods for traversing the route tree.</td></tr><tr><td style="text-align:left;">Link parameters array</td><td style="text-align:left;">An array that the router interprets as a routing instruction. You can bind that array to a <code>RouterLink</code> or pass the array as an argument to the <code>Router.navigate</code> method.</td></tr><tr><td style="text-align:left;">Routing component</td><td style="text-align:left;">An Angular component with a <code>RouterOutlet</code> that displays views based on router navigations.</td></tr></tbody></table><h2 id="base-href" tabindex="-1"><code>&lt;base href&gt;</code> <a class="header-anchor" href="#base-href" aria-label="Permalink to &quot;`&lt;base href&gt;`&quot;">​</a></h2><p>The router uses the browser&#39;s <a href="https://developer.mozilla.org/docs/Web/API/History_API/Working_with_the_History_API#adding_and_modifying_history_entries" title="HTML5 browser history push-state" target="_blank" rel="noreferrer">history.pushState</a> for navigation. <code>pushState</code> lets you customize in-application URL paths; for example, <code>localhost:4200/crisis-center</code>. The in-application URLs can be indistinguishable from server URLs.</p><p>Modern HTML5 browsers were the first to support <code>pushState</code> which is why many people refer to these URLs as &quot;HTML5 style&quot; URLs.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>HTML5 style navigation is the router default. In the <a href="/en/guide/routing/common-router-tasks#locationstrategy-and-browser-url-styles">LocationStrategy and browser URL styles</a> section, learn why HTML5 style is preferable, how to adjust its behavior, and how to switch to the older hash (<code>#</code>) style, if necessary.</p></div><p>You must add a <a href="https://developer.mozilla.org/docs/Web/HTML/Element/base" title="base href" target="_blank" rel="noreferrer"><code>&lt;base href&gt;</code> element</a> to the application&#39;s <code>index.html</code> for <code>pushState</code> routing to work. The browser uses the <code>&lt;base href&gt;</code> value to prefix relative URLs when referencing CSS files, scripts, and images.</p><p>Add the <code>&lt;base&gt;</code> element just after the <code>&lt;head&gt;</code> tag. If the <code>app</code> folder is the application root, as it is for this application, set the <code>href</code> value in <code>index.html</code> as shown here.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">base</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/en/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><h3 id="html5-urls-and-the-base-href" tabindex="-1">HTML5 URLs and the <code>&lt;base href&gt;</code> <a class="header-anchor" href="#html5-urls-and-the-base-href" aria-label="Permalink to &quot;HTML5 URLs and the `&lt;base href&gt;`&quot;">​</a></h3><p>The guidelines that follow will refer to different parts of a URL. This diagram outlines what those parts refer to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>foo://example.com:8042/over/there?name=ferret#nose</span></span>\n<span class="line"><span>\\_/   \\______________/\\_________/ \\_________/ \\__/</span></span>\n<span class="line"><span> |           |            |            |        |</span></span>\n<span class="line"><span>scheme    authority      path        query   fragment</span></span></code></pre></div><p>While the router uses the <a href="https://developer.mozilla.org/docs/Web/API/History_API#Adding_and_modifying_history_entries" title="Browser history push-state" target="_blank" rel="noreferrer">HTML5 pushState</a> style by default, you must configure that strategy with a <code>&lt;base href&gt;</code>.</p><p>The preferred way to configure the strategy is to add a <a href="https://developer.mozilla.org/docs/Web/HTML/Element/base" title="base href" target="_blank" rel="noreferrer"><code>&lt;base href&gt;</code> element</a> tag in the <code>&lt;head&gt;</code> of the <code>index.html</code>.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">base</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/en/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Without that tag, the browser might not be able to load resources (images, CSS, scripts) when &quot;deep linking&quot; into the application.</p><p>Some developers might not be able to add the <code>&lt;base&gt;</code> element, perhaps because they don&#39;t have access to <code>&lt;head&gt;</code> or the <code>index.html</code>.</p><p>Those developers can still use HTML5 URLs by taking the following two steps:</p><ol><li>Provide the router with an appropriate <code>APP_BASE_HREF</code> value.</li><li>Use root URLs (URLs with an <code>authority</code>) for all web resources: CSS, images, scripts, and template HTML files. <ul><li><p>The <code>&lt;base href&gt;</code> <code>path</code> should end with a &quot;/&quot;, as browsers ignore characters in the <code>path</code> that follow the right-most &quot;<code>/</code>&quot;</p></li><li><p>If the <code>&lt;base href&gt;</code> includes a <code>query</code> part, the <code>query</code> is only used if the <code>path</code> of a link in the page is empty and has no <code>query</code>. This means that a <code>query</code> in the <code>&lt;base href&gt;</code> is only included when using <code>HashLocationStrategy</code>.</p></li><li><p>If a link in the page is a root URL (has an <code>authority</code>), the <code>&lt;base href&gt;</code> is not used. In this way, an <code>APP_BASE_HREF</code> with an authority will cause all links created by Angular to ignore the <code>&lt;base href&gt;</code> value.</p></li><li><p>A fragment in the <code>&lt;base href&gt;</code> is <em>never</em> persisted</p></li></ul></li></ol><p>For more complete information on how <code>&lt;base href&gt;</code> is used to construct target URIs, see the <a href="https://tools.ietf.org/html/rfc3986#section-5.2.2" target="_blank" rel="noreferrer">RFC</a> section on transforming references.</p><h3 id="hashlocationstrategy" tabindex="-1"><code>HashLocationStrategy</code> <a class="header-anchor" href="#hashlocationstrategy" aria-label="Permalink to &quot;`HashLocationStrategy`&quot;">​</a></h3><p>Use <code>HashLocationStrategy</code> by providing the <code>useHash: true</code> in an object as the second argument of the <code>RouterModule.forRoot()</code> in the <code>AppModule</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provideRouter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(appRoutes, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withHashLocation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())];</span></span></code></pre></div><p>When using <code>RouterModule.forRoot</code>, this is configured with the <code>useHash: true</code> in the second argument: <code>RouterModule.forRoot(routes, {useHash: true})</code>.</p>',31)]))}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
